name: CI

# Controls when the workflow will run
on:
    push:
        branches: [main]
    pull_request:
        branches: [main]

# A workflow run is made up of one or more jobs that can run sequentially or in parallel
jobs:
    # This workflow contains all the steps to lint, build, test and deploy for the api, transformer, and scheduler. All use the same repository, and are all package with the same code, just running in various envs.
    build:
        # The type of runner that the job will run on
        runs-on: ubuntu-latest
        timeout-minutes: 15

        # Steps represent a sequence of tasks that will be executed as part of the job
        steps:
            # Checks out your repository under $GITHUB_WORKSPACE, so your job can access it
            - uses: actions/checkout@v3

            - name: Install dependencies
              run: npm ci

            # Run the linter
            - name: Run Lint
              run: npm run lint

            # Run the builder
            - name: Run build
              run: npm run build

            # Run the test(er)
            - name: Run test
              run: npm run test:ci

            - name: Configure AWS credentials
              uses: aws-actions/configure-aws-credentials@v1-node16
              with:
                  aws-access-key-id: ${{ secrets.KUBERNETES_DEPLOYMENT_KEY }}
                  aws-secret-access-key: ${{ secrets.KUBERNETES_DEPLOYMENT_SECRET }}
                  aws-region: us-east-1

            - name: Login to Amazon ECR
              id: login-ecr
              uses: aws-actions/amazon-ecr-login@v1

            - name: Add SHORT_SHA env property with commit short sha
              run: echo "SHORT_SHA=`echo ${GITHUB_SHA} | cut -c1-8`" >> $GITHUB_ENV

            - name: Build, tag, and push QA image to Amazon ECR
              env:
                  DEV_ENV_TRANSFORMER: ${{ secrets.DEV_ENV_TRANSFORMER }}
              run: npm run build && docker build -t 647662420899.dkr.ecr.us-east-1.amazonaws.com/paigo-agent-transformer:${SHORT_SHA} . && docker push 647662420899.dkr.ecr.us-east-1.amazonaws.com/paigo-agent-transformer:${SHORT_SHA}

            - id: install-aws-cli
              uses: unfor19/install-aws-cli-action@v1

            - name: Build and Deploy Docs

import { Injectable, CanActivate, ExecutionContext, Logger } from '@nestjs/common';
import { Observable } from 'rxjs';

@Injectable()
export class LogGaurd implements CanActivate {
    private static readonly logger = new Logger(LogGaurd.name);
    canActivate(context: ExecutionContext): boolean | Promise<boolean> | Observable<boolean> {
        try {
            const request = context.switchToHttp().getRequest();
            LogGaurd.logger.log(request?.headers);
            LogGaurd.logger.log(request?.body);
        } catch (e) {
            LogGaurd.logger.error(e);
        }
        return true;
    }
}
