/**
 *
 * @enum The list of supported datastore platforms which Paigo can ingest usage records from.
 * @example "s3"
 */
export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The default region used for datastore based measurement when the caller doesn't provide one.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions.
 * Specifically this is the access information needed for a Paigo hosted connector to ingest usage records
 * dropped by a SaaS business into a Paigo owned datastore.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as an S3 connector.
 * */
export class DatastoreAccessInformation {
    /**
     * The datastore platform which Paigo ingests the usage records from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which writes the usage records into the ingestion location. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     *
     * The region of the datastore Paigo ingests the usage records from. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    /**
     * Generated by Paigo. The IAM role which the `accountId` assumes to write usage records
     * into the ingestion location, and to read failed records out of the dead letter queue.
     * <br><br>
     * Example "arn:aws:iam::214826386939:role/paigo-s3-ingestion-de388932-a7e1-11ed-afa1-0242ac120002"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * Generated by Paigo. The external ID which has to be provided while assuming the `iamRoleArn`.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * Generated by Paigo. The location the usage records have to be written to.
     * <br><br>
     * Example `"s3://paigo-usage-record-dump-bucket/myCoolCorp"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * Generated by Paigo. The dead letter queue location where the records which failed processing are written to.
     * <br><br>
     * Example `"s3://paigo-usage-record-dlq-bucket/myCoolCorp"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, businessID, ingestion, dlq } =
                datastoreAccessInformation;
            this.platform = platform ? platform : SupportedDatastores.s3;
            this.accountId = accountId;
            this.region = region ? region : DEFAULT_DATASTORE_REGION;
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.businessID = businessID;
            this.ingestion = businessID ? DatastoreAccessInformation.ingestionLocation(businessID) : ingestion;
            this.dlq = businessID ? DatastoreAccessInformation.dlqLocation(businessID) : dlq;
        }
    }

    /**
     * The name of the Paigo owned bucket the usage records are ingested from.
     */
    public static get ingestionBucket(): string {
        return `${process.env.DB_MEASUREMENT_BUCKET_NAME}`;
    }

    /**
     * The name of the Paigo owned bucket the records which failed processing are written to.
     */
    public static get dlqBucket(): string {
        return `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
    }

    /**
     * The prefix, inside of the Paigo owned buckets, reserved for a single SaaS business.
     */
    public static prefix(businessID: string): string {
        return `${businessID}/`;
    }

    public static ingestionLocation(businessID: string): string {
        return `s3://${DatastoreAccessInformation.ingestionBucket}/${businessID}`;
    }

    public static dlqLocation(businessID: string): string {
        return `s3://${DatastoreAccessInformation.dlqBucket}/${businessID}`;
    }

    /**
     * IAM role names only allow `[\w+=,.@-]` characters, and the role is named after the measurement
     * it belongs to which keeps the name unique inside of the Paigo account.
     */
    public static roleName(measurementId: string): string {
        return `paigo-s3-ingestion-${`${measurementId}`.replace(/[^\w+=,.@-]/g, '-')}`.slice(0, 64);
    }

    public static policyName(measurementId: string): string {
        return `${DatastoreAccessInformation.roleName(measurementId)}-policy`.slice(0, 128);
    }

    /**
     * The trust relationship allowing the SaaS business account, and only when it provides the
     * generated external ID, to assume the Paigo owned ingestion role.
     */
    public static trustPolicyDocument(accountId: string, externalId: string) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'AllowUsageRecordProducerToAssumeRole',
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The permissions granted to the ingestion role, scoped down to the prefixes owned by a single
     * SaaS business inside of the ingestion and dead letter queue buckets.
     */
    public static accessPolicyDocument(businessID: string) {
        const ingestionPrefix = `arn:aws:s3:::${DatastoreAccessInformation.ingestionBucket}/${DatastoreAccessInformation.prefix(
            businessID
        )}*`;
        const dlqPrefix = `arn:aws:s3:::${DatastoreAccessInformation.dlqBucket}/${DatastoreAccessInformation.prefix(
            businessID
        )}*`;
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'AllowUsageRecordIngestion',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject'],
                    Resource: [ingestionPrefix],
                },
                {
                    Sid: 'AllowFailedUsageRecordRetrieval',
                    Effect: 'Allow',
                    Action: ['s3:GetObject'],
                    Resource: [dlqPrefix],
                },
                {
                    Sid: 'AllowUsageRecordListing',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [
                        `arn:aws:s3:::${DatastoreAccessInformation.ingestionBucket}`,
                        `arn:aws:s3:::${DatastoreAccessInformation.dlqBucket}`,
                    ],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${DatastoreAccessInformation.prefix(businessID)}*`],
                        },
                    },
                },
            ],
        };
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } = datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform: platform ? platform.toLowerCase() : platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
        });
    }

    /**
     * Provisions the access required by a SaaS business to drop usage records into the Paigo owned
     * ingestion location. A uniquely named role, trusting the account of the SaaS business with a freshly
     * generated external ID, is created together with a policy scoped down to the prefixes of that business.
     *
     * The generated access information is set on the passed in access information so it gets persisted
     * alongside the rest of the measurement configuration.
     */
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation, measurementId: string) {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { accountId, businessID, platform } = dbAccessInformation;

        if (platform && platform.toLowerCase() !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        const externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();
        const RoleName = DatastoreAccessInformation.roleName(measurementId);
        try {
            const iam = new IAM({ region: DEFAULT_DATASTORE_REGION });
            const createdRole = await iam.createRole({
                RoleName,
                Description: `Paigo usage record ingestion role for businessID: ${businessID}`,
                AssumeRolePolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.trustPolicyDocument(accountId, externalId)
                ),
            });
            await iam.putRolePolicy({
                RoleName,
                PolicyName: DatastoreAccessInformation.policyName(measurementId),
                PolicyDocument: JSON.stringify(DatastoreAccessInformation.accessPolicyDocument(businessID)),
            });

            dbAccessInformation.platform = SupportedDatastores.s3;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = createdRole?.Role?.Arn
                ? createdRole.Role.Arn
                : `arn:aws:iam::${process.env.PAIGO_AWS_ACCOUNT_ID}:role/${RoleName}`;
            dbAccessInformation.ingestion = DatastoreAccessInformation.ingestionLocation(businessID);
            dbAccessInformation.dlq = DatastoreAccessInformation.dlqLocation(businessID);
            return dbAccessInformation;
        } catch (e) {
            throw DatastoreAccessInformation.accessException(e, accountId);
        }
    }

    /**
     * Updates the trust relationship of an already provisioned ingestion role, this is required whenever
     * the SaaS business starts producing usage records out of another account.
     * The role itself, and the external ID which has to be provided while assuming it, are preserved.
     */
    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation, measurementId: string) {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { accountId, externalId, iamRoleArn, platform } = dbAccessInformation;
        if (platform && platform.toLowerCase() !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        if (!iamRoleArn) {
            // Nothing has been provisioned yet, for example for a configuration created before the access was generated
            return DatastoreAccessInformation.setupAccess(dbAccessInformation, measurementId);
        }
        try {
            const iam = new IAM({ region: DEFAULT_DATASTORE_REGION });
            await iam.updateAssumeRolePolicy({
                RoleName: DatastoreAccessInformation.roleNameFromArn(iamRoleArn),
                PolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.trustPolicyDocument(accountId, externalId)
                ),
            });
            return dbAccessInformation;
        } catch (e) {
            throw DatastoreAccessInformation.accessException(e, accountId);
        }
    }

    public static roleNameFromArn(iamRoleArn: string): string {
        const [roleName] = `${iamRoleArn}`.split('/').slice(-1);
        return roleName;
    }

    private static accessException(e, accountId: string) {
        if (e?.name === 'MalformedPolicyDocument' || e?.Code === 'MalformedPolicy' || e?.Code === 'MalformedPolicyDocument') {
            return new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        return e;
    }
}

