import { S3 } from '@aws-sdk/client-s3';
import { Logger } from '@nestjs/common';
import {
    DatastoreAccessInformation,
    DEFAULT_DATASTORE_REGION,
} from '../../measurement-config/entities/measurement-config.entity';
import { CreateUsageDto } from '../dto/create-usage.dto';

/**
 * The suffix appended to the mirrored source key of a record which failed processing.
 */
export const DLQ_KEY_SUFFIX = '.message.text';

/**
 * A single usage record dropped by a SaaS business into the Paigo owned ingestion location and
 * forwarded to the private API by the internal datastore connector.
 *
 * The connector has no knowledge about the shape of a usage record, every record which cannot be
 * processed is mirrored into the dead letter queue of the SaaS business which produced it.
 */
export class DatastoreUsageRecord {
    private static readonly logger = new Logger(DatastoreUsageRecord.name);

    /**
     * The key of the object inside of the ingestion bucket, relative to the bucket itself.
     * The connector may report the key as a fully qualified S3 URI, as a bucket prefixed key, or
     * as a key which is already relative to the ingestion bucket.
     */
    public static sourceKey(s3Key: string): string {
        const withoutScheme = `${s3Key}`.trim().replace(/^s3:\/\//i, '');
        const bucket = DatastoreAccessInformation.ingestionBucket;
        const withoutBucket = withoutScheme.startsWith(`${bucket}/`)
            ? withoutScheme.slice(`${bucket}/`.length)
            : withoutScheme;
        return withoutBucket.replace(/^\/+/, '');
    }

    /**
     * Every SaaS business owns a prefix inside of the ingestion bucket, the first segment of the
     * source key is therefore the businessID which produced the usage record.
     */
    public static businessID(sourceKey: string): string {
        const [businessID] = `${sourceKey}`.split('/');
        return businessID;
    }

    /**
     * The dead letter queue mirrors the source key of the record which failed processing, that way a
     * SaaS business can correlate a failure with the record it produced.
     */
    public static dlqKey(sourceKey: string): string {
        return `${sourceKey}${DLQ_KEY_SUFFIX}`;
    }

    /**
     * A record holds a single standard usage record as JSON.
     *
     * @throws when the record isn't a parsable usage record
     */
    public static parse(message: string | CreateUsageDto): CreateUsageDto {
        const parsed = typeof message === 'string' ? JSON.parse(message) : message;
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || !Object.keys(parsed).length) {
            throw new Error('The message is not a usage record');
        }
        return parsed;
    }

    /**
     * Writes a record which failed processing, together with the metadata of the failure,
     * into the dead letter queue of the SaaS business which produced it.
     */
    public static async publishToDLQ({
        message,
        s3Key,
        sourceKey,
        businessID,
        error,
    }: {
        message?: string | CreateUsageDto;
        s3Key: string;
        sourceKey: string;
        businessID?: string;
        error?: Error | string;
    }) {
        const Bucket = DatastoreAccessInformation.dlqBucket;
        const Key = DatastoreUsageRecord.dlqKey(sourceKey);
        const Body = JSON.stringify(
            {
                message,
                s3Key,
                sourceKey,
                businessID,
                error: error instanceof Error ? error.message : error,
                processedAt: new Date().toISOString(),
            },
            null,
            2
        );
        DatastoreUsageRecord.logger.warn(`Writing failed usage record to the dead letter queue: s3://${Bucket}/${Key}`);
        const s3 = new S3({ region: DEFAULT_DATASTORE_REGION });
        await s3.putObject({ Bucket, Key, Body, ContentType: 'application/json' });
        return { Bucket, Key };
    }
}

arguments.newString:
    /**
     * Collect a single usage record gathered by the internal datastore connector.
     * Records which cannot be processed are written to the dead letter queue of the
     * SaaS business which produced them.
     */
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto) {
        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto;
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        if (!s3Key) {
            throw new BadRequestException('An s3Key must be provided alongside the usage record');
        }
        const sourceKey = DatastoreUsageRecord.sourceKey(s3Key);
        const businessID = DatastoreUsageRecord.businessID(sourceKey);
        try {
            if (!businessID) {
                throw new Error(`Unable to determine the businessID out of the s3Key: ${s3Key}`);
            }
            const parsed = DatastoreUsageRecord.parse(message);
            return await this.usageService.create({ ...parsed, businessID });
        } catch (error) {
            UsageController.logger.error(`Failed to process the usage record stored at: ${s3Key}`, error);
            const { Bucket, Key } = await DatastoreUsageRecord.publishToDLQ({
                message,
                s3Key,
                sourceKey,
                businessID,
                error,
            });
            return { message: `Failed to process usage record, written to the DLQ: s3://${Bucket}/${Key}` };
        }
    }
}

