import { CreateRoleCommand, IAM, PutRolePolicyCommand, UpdateAssumeRolePolicyCommand } from '@aws-sdk/client-iam';
import { mockClient } from 'aws-sdk-client-mock';
import {
    DatastoreAccessInformation,
    DEFAULT_DATASTORE_REGION,
    SupportedDatastores,
} from './measurement-config.entity';

const INGESTION_BUCKET = 'paigo-usage-record-dump-bucket';
const DLQ_BUCKET = 'paigo-usage-record-dlq-bucket';

describe('DatastoreAccessInformation', () => {
    const iamMock = mockClient(IAM);
    const businessID = 'fakeBusiness';
    const accountId = '623673123435';
    const measurementId = 'de388932-a7e1-11ed-afa1-0242ac120002';
    const createdRoleArn = `arn:aws:iam::214826386939:role/paigo-s3-ingestion-${measurementId}`;

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = INGESTION_BUCKET;
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = DLQ_BUCKET;
    });

    beforeEach(() => {
        iamMock.reset();
        iamMock.on(CreateRoleCommand).resolves({ Role: { Arn: createdRoleArn } as never });
    });

    it('defaults the platform and the region', () => {
        const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as never);

        expect(accessInformation.platform).toEqual(SupportedDatastores.s3);
        expect(accessInformation.region).toEqual(DEFAULT_DATASTORE_REGION);
        expect(accessInformation.accountId).toEqual(accountId);
    });

    it('keeps the provided platform and region', () => {
        const accessInformation = new DatastoreAccessInformation({
            accountId,
            businessID,
            platform: SupportedDatastores.s3,
            region: 'eu-west-1',
        } as never);

        expect(accessInformation.region).toEqual('eu-west-1');
    });

    it('provisions a uniquely named role trusting the account of the business with a fresh external id', async () => {
        const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as never);

        const provisioned = await DatastoreAccessInformation.setupAccess(accessInformation, measurementId);

        expect(provisioned.iamRoleArn).toEqual(createdRoleArn);
        expect(provisioned.externalId).toBeTruthy();
        expect(provisioned.ingestion).toEqual(`s3://${INGESTION_BUCKET}/${businessID}`);
        expect(provisioned.dlq).toEqual(`s3://${DLQ_BUCKET}/${businessID}`);

        const [createRole] = iamMock.commandCalls(CreateRoleCommand);
        expect(createRole.args[0].input.RoleName).toEqual(`paigo-s3-ingestion-${measurementId}`);
        expect(JSON.parse(createRole.args[0].input.AssumeRolePolicyDocument)).toEqual({
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'AllowUsageRecordProducerToAssumeRole',
                    Effect: 'Allow',
                    Principal: { AWS: `arn:aws:iam::${accountId}:root` },
                    Action: 'sts:AssumeRole',
                    Condition: { StringEquals: { 'sts:ExternalId': provisioned.externalId } },
                },
            ],
        });
    });

    it('scopes the policy of the provisioned role to the prefixes of the business', async () => {
        const accessInformation = new DatastoreAccessInformation({ accountId, businessID } as never);

        await DatastoreAccessInformation.setupAccess(accessInformation, measurementId);

        const [putRolePolicy] = iamMock.commandCalls(PutRolePolicyCommand);
        expect(putRolePolicy.args[0].input.PolicyName).toEqual(`paigo-s3-ingestion-${measurementId}-policy`);
        const { Statement } = JSON.parse(putRolePolicy.args[0].input.PolicyDocument);
        const resources = Statement.reduce((acc, { Resource }) => [...acc, ...Resource], []);
        expect(resources).toContain(`arn:aws:s3:::${INGESTION_BUCKET}/${businessID}/*`);
        expect(resources).toContain(`arn:aws:s3:::${DLQ_BUCKET}/${businessID}/*`);
        expect(resources).not.toContain(`arn:aws:s3:::${INGESTION_BUCKET}/*`);
    });

    it('generates a different role and external id per measurement', async () => {
        const first = await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({ accountId, businessID } as never),
            measurementId
        );
        const second = await DatastoreAccessInformation.setupAccess(
            new DatastoreAccessInformation({ accountId, businessID } as never),
            'a4e0a0f4-a7e1-11ed-afa1-0242ac120002'
        );

        const [firstCall, secondCall] = iamMock.commandCalls(CreateRoleCommand);
        expect(firstCall.args[0].input.RoleName).not.toEqual(secondCall.args[0].input.RoleName);
        expect(first.externalId).not.toEqual(second.externalId);
    });

    it('updates the trust of the role while preserving the role and the external id', async () => {
        const accessInformation = new DatastoreAccessInformation({
            accountId: '999999999999',
            businessID,
            iamRoleArn: createdRoleArn,
            externalId: 'existing-external-id',
        } as never);

        const updated = await DatastoreAccessInformation.updateAccess(accessInformation, measurementId);

        expect(updated.iamRoleArn).toEqual(createdRoleArn);
        expect(updated.externalId).toEqual('existing-external-id');
        expect(iamMock.commandCalls(CreateRoleCommand).length).toEqual(0);
        const [updateTrust] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        expect(updateTrust.args[0].input.RoleName).toEqual(`paigo-s3-ingestion-${measurementId}`);
        const { Statement } = JSON.parse(updateTrust.args[0].input.PolicyDocument);
        expect(Statement[0].Principal.AWS).toEqual('arn:aws:iam::999999999999:root');
        expect(Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual('existing-external-id');
    });

    it('round trips through the DB model', () => {
        const accessInformation = new DatastoreAccessInformation({
            accountId,
            businessID,
            iamRoleArn: createdRoleArn,
            externalId: 'existing-external-id',
        } as never);
        const tags = {};
        const influxPoint = { tag: (key, value) => (tags[key] = value) };

        DatastoreAccessInformation.transformer(accessInformation, influxPoint as never);

        expect(tags).toEqual({
            platform: 's3',
            accountId,
            region: DEFAULT_DATASTORE_REGION,
            iamRoleArn: createdRoleArn,
            externalId: 'existing-external-id',
            ingestion: `s3://${INGESTION_BUCKET}/${businessID}`,
            dlq: `s3://${DLQ_BUCKET}/${businessID}`,
        });
        expect(DatastoreAccessInformation.dbModelToEntity({ ...tags, businessID })).toEqual(accessInformation);
    });
});

