     *
     * The generated access information is set on the passed in access information so it gets persisted
     * alongside the rest of the measurement configuration.
     */
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation, measurementId: string) {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        if (!DatastoreAccessInformation.isS3(dbAccessInformation)) {
