    public static isS3({ platform }: DatastoreAccessInformation): boolean {
        return !platform || `${platform}`.toLowerCase() === SupportedDatastores.s3;
    }

    public static roleNameFromArn(iamRoleArn: string): string {
        const [roleName] = `${iamRoleArn}`.split('/').slice(-1);
        return roleName;
    }

    /**
     * An invalid account is the only failure a SaaS business can act on, every other failure is logged
     * so the access of the stored measurement configuration can be reconciled.
     */
    private static handleAccessException(
        e,
