        action: 'provision' | 'update'
    ): void {
        const invalidAccount = DatastoreAccessInformation.accessException(e, accountId);
        if (invalidAccount) {
            throw invalidAccount;
        }
        MeasurementConfigEntity.logger.error(`Failed to ${action} the datastore ingestion access`, e);
    }

