    });

    it('round trips through the DB model', () => {
        const iamRoleArn = `arn:aws:iam::${PAIGO_AWS_ACCOUNT_ID}:role/paigo-s3-ingestion-${measurementId}`;
        const accessInformation = new DatastoreAccessInformation({
            accountId,
            businessID,
            iamRoleArn,
            externalId: 'existing-external-id',
        } as never);
        const tags = {};
        const influxPoint = { tag: (key, value) => (tags[key] = value) };

        DatastoreAccessInformation.transformer(accessInformation, influxPoint as never);

        expect(tags).toEqual({
            platform: 's3',
            accountId,
            region: DEFAULT_DATASTORE_REGION,
            iamRoleArn,
            externalId: 'existing-external-id',
            ingestion: `s3://${INGESTION_BUCKET}/${businessID}`,
            dlq: `s3://${DLQ_BUCKET}/${businessID}`,
        });
        expect(DatastoreAccessInformation.dbModelToEntity({ ...tags, businessID })).toEqual(accessInformation);
    });
});

import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { UsageController } from '../usage.controller';
import { DatastoreUsageRecord, DLQ_KEY_SUFFIX } from './datastoreUsage.entity';

const INGESTION_BUCKET = 'paigo-usage-record-dump-bucket';
const DLQ_BUCKET = 'paigo-usage-record-dlq-bucket';

describe('Datastore based usage collection', () => {
    const s3Mock = mockClient(S3Client);
    const businessID = 'fakeBusiness';
    const usageRecord = {
        timeStamp: '2023-02-08T19:24:10Z',
        dimensionId: 'da9611bd-e0f3-4c0d-a754-fda5be730872',
        serviceId: 'e8366954-6f36-47e9-8431-ac95f88b5cc7',
        recordValue: '0.87',
    };
    const mockCreate = jest.fn();
    const controller = new UsageController({ create: mockCreate } as never);

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = INGESTION_BUCKET;
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = DLQ_BUCKET;
    });

    beforeEach(() => {
        s3Mock.reset();
        mockCreate.mockResolvedValue({ message: 'Measurement created' });
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('resolves the source key of a record reported with the bucket, as an URI, or relative', () => {
        expect(DatastoreUsageRecord.sourceKey(`${businessID}/records/1.json`)).toEqual(
            `${businessID}/records/1.json`
        );
        expect(DatastoreUsageRecord.sourceKey(`${INGESTION_BUCKET}/${businessID}/records/1.json`)).toEqual(
            `${businessID}/records/1.json`
        );
        expect(DatastoreUsageRecord.sourceKey(`s3://${INGESTION_BUCKET}/${businessID}/records/1.json`)).toEqual(
            `${businessID}/records/1.json`
        );
    });

    it('collects a valid record through the usage service with the businessID of the source key', async () => {
        const response = await controller.dbUsage({
            message: JSON.stringify(usageRecord),
            s3Key: `${businessID}/records/1.json`,
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...usageRecord, businessID });
        expect(response).toEqual({ message: 'Measurement created' });
        expect(s3Mock.commandCalls(PutObjectCommand).length).toEqual(0);
    });

    it('collects a valid record reported with a fully qualified source key', async () => {
        await controller.dbUsage({
            message: JSON.stringify(usageRecord),
            s3Key: `s3://${INGESTION_BUCKET}/${businessID}/records/1.json`,
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...usageRecord, businessID });
    });

    it('writes a malformed record to the DLQ mirroring the source key', async () => {
        const s3Key = `${businessID}/records/broken.json`;

        await controller.dbUsage({ message: '{"recordValue": ', s3Key });

        expect(mockCreate).not.toHaveBeenCalled();
        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual(DLQ_BUCKET);
        expect(putObject.args[0].input.Key).toEqual(`${s3Key}${DLQ_KEY_SUFFIX}`);
        const dlqRecord = JSON.parse(`${putObject.args[0].input.Body}`);
        expect(dlqRecord.message).toEqual('{"recordValue": ');
        expect(dlqRecord.s3Key).toEqual(s3Key);
        expect(dlqRecord.businessID).toEqual(businessID);
        expect(dlqRecord.error).toBeTruthy();
        expect(dlqRecord.processedAt).toBeTruthy();
    });

    it('writes a malformed record reported with an already relative source key to the DLQ', async () => {
        await controller.dbUsage({
            message: 'not a usage record',
            s3Key: `s3://${INGESTION_BUCKET}/${businessID}/records/broken.json`,
        });

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Key).toEqual(`${businessID}/records/broken.json${DLQ_KEY_SUFFIX}`);
    });

    it('rejects a record without a source key', async () => {
        await expect(controller.dbUsage({ message: JSON.stringify(usageRecord) })).rejects.toThrow(
            'An s3Key must be provided alongside the usage record'
        );
        expect(mockCreate).not.toHaveBeenCalled();
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { DimensionsService } from '../dimensions/dimensions.service';
import { InfluxService } from '../influx/influx.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { measurementMode } from './dto/create-measurement-config.dto';
import {
    DatastoreAccessInformation,
    DEFAULT_DATASTORE_REGION,
    PAIGO_AWS_ACCOUNT_ID,
    supportedCloudPlatforms,
    SupportedResources,
} from './entities/measurement-config.entity';
import { MeasurementConfigService } from './measurement-config.service';

const mockCreateRole = jest.fn();
const mockPutRolePolicy = jest.fn();
const mockUpdateAssumeRolePolicy = jest.fn();

jest.mock('@aws-sdk/client-iam', () => ({
    IAM: jest.fn().mockImplementation(() => ({
        createRole: (...args) => mockCreateRole(...args),
        putRolePolicy: (...args) => mockPutRolePolicy(...args),
        updateAssumeRolePolicy: (...args) => mockUpdateAssumeRolePolicy(...args),
    })),
}));

const INGESTION_BUCKET = 'paigo-usage-record-dump-bucket';
const DLQ_BUCKET = 'paigo-usage-record-dlq-bucket';

describe('MeasurementConfigService datastore based measurements', () => {
    let service: MeasurementConfigService;
    const businessID = 'fakeBusiness';
    const subject = 'fakeSubject';
    const accountId = '623673123435';
    const storedMeasurementId = 'de388932-a7e1-11ed-afa1-0242ac120002';
    const storedIamRoleArn = `arn:aws:iam::${PAIGO_AWS_ACCOUNT_ID}:role/paigo-s3-ingestion-${storedMeasurementId}`;
    const mockLoadPoints = jest.fn();
    let points: Array<Record<string, string>>;
    let storedMeasurements: Array<Record<string, string>>;

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = INGESTION_BUCKET;
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = DLQ_BUCKET;
    });

    beforeEach(async () => {
        points = [];
        storedMeasurements = [
            {
                measurementId: storedMeasurementId,
                _value: measurementMode.datastoreBased,
                businessID,
                measurementName: 'my datastore measurement',
                subject,
                platform: 's3',
                accountId,
                region: DEFAULT_DATASTORE_REGION,
                iamRoleArn: storedIamRoleArn,
                externalId: 'existing-external-id',
                ingestion: `s3://${INGESTION_BUCKET}/${businessID}`,
                dlq: `s3://${DLQ_BUCKET}/${businessID}`,
            },
        ];
        const module: TestingModule = await Test.createTestingModule({
            providers: [MeasurementConfigService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => {
                            const tags = {};
                            points.push(tags);
                            return { tag: (key, value) => (tags[key] = value), stringField: () => undefined };
                        },
                        readMeasurementConfigData: () => storedMeasurements,
                        readAllMeaurements: () => storedMeasurements,
                        readMeasurementConfigDataByDimensionId: () => [],
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn() };
                }
                if (token === DimensionsService) {
                    return { transformDtoToEntityInput: jest.fn(), findOneByDimensionId: jest.fn() };
                }
            })
            .compile();

        service = module.get<MeasurementConfigService>(MeasurementConfigService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('returns and persists the generated access alongside the configuration', async () => {
        const { measurementId, measurementConfiguration } = await service.create(
            {
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as never,
                businessID,
                measurementName: 'my datastore measurement',
            },
            subject
        );

        expect(measurementConfiguration).toEqual({
            platform: 's3',
            accountId,
            region: DEFAULT_DATASTORE_REGION,
            iamRoleArn: `arn:aws:iam::${PAIGO_AWS_ACCOUNT_ID}:role/paigo-s3-ingestion-${measurementId}`,
            externalId: expect.any(String),
            ingestion: `s3://${INGESTION_BUCKET}/${businessID}`,
            dlq: `s3://${DLQ_BUCKET}/${businessID}`,
            businessID,
        });
        expect(mockCreateRole).toHaveBeenCalledTimes(1);
        expect(mockPutRolePolicy).toHaveBeenCalledTimes(1);
        expect(mockLoadPoints).toHaveBeenCalledTimes(1);
        const [persisted] = points;
        expect(persisted).toEqual({
            measurementId,
            businessID,
            subject,
            measurementName: 'my datastore measurement',
            platform: 's3',
            accountId,
            region: DEFAULT_DATASTORE_REGION,
            iamRoleArn: (measurementConfiguration as DatastoreAccessInformation).iamRoleArn,
            externalId: (measurementConfiguration as DatastoreAccessInformation).externalId,
            ingestion: `s3://${INGESTION_BUCKET}/${businessID}`,
            dlq: `s3://${DLQ_BUCKET}/${businessID}`,
        });
    });

    it('reads back the stored configuration of a datastore based measurement', async () => {
        const {
            data: [measurement],
        } = await service.findOne({ measurementId: storedMeasurementId, businessID });

        expect(measurement.measurementMode).toEqual(measurementMode.datastoreBased);
        expect(measurement.measurementConfiguration).toEqual({
            platform: 's3',
            accountId,
            region: DEFAULT_DATASTORE_REGION,
            iamRoleArn: storedIamRoleArn,
            externalId: 'existing-external-id',
            ingestion: `s3://${INGESTION_BUCKET}/${businessID}`,
            dlq: `s3://${DLQ_BUCKET}/${businessID}`,
            businessID,
        });
    });

    it('updates the trust of the role when the account changes and preserves the role and external id', async () => {
        const { measurementConfiguration } = await service.update(
            {
                measurementId: storedMeasurementId,
                businessID,
                measurementName: undefined,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId: '999999999999', iamRoleArn: 'arn:aws:iam::1:role/hijacked' },
            },
            subject
        );

        expect(measurementConfiguration).toEqual({
            platform: 's3',
            accountId: '999999999999',
            region: DEFAULT_DATASTORE_REGION,
            iamRoleArn: storedIamRoleArn,
            externalId: 'existing-external-id',
            ingestion: `s3://${INGESTION_BUCKET}/${businessID}`,
            dlq: `s3://${DLQ_BUCKET}/${businessID}`,
            businessID,
        });
        expect(mockCreateRole).not.toHaveBeenCalled();
        const [[{ RoleName, PolicyDocument }]] = mockUpdateAssumeRolePolicy.mock.calls;
        expect(RoleName).toEqual(`paigo-s3-ingestion-${storedMeasurementId}`);
        expect(PolicyDocument).toContain('arn:aws:iam::999999999999:root');
        expect(PolicyDocument).toContain('existing-external-id');
    });

    it('does not touch the provisioned access when only the name is updated', async () => {
        await service.update(
            {
                measurementId: storedMeasurementId,
                businessID,
                measurementName: 'renamed',
                measurementMode: measurementMode.datastoreBased,
            },
            subject
        );

        expect(mockUpdateAssumeRolePolicy).not.toHaveBeenCalled();
        expect(mockCreateRole).not.toHaveBeenCalled();
    });

    it('leaves infrastructure based measurements untouched', async () => {
        const response = await service.create(
            {
                measurementMode: measurementMode.infrastructureBased,
                measurementConfiguration: {
                    iamRoleArn: 'fakeARN',
                    externalId: 'fakeID',
                    cloudPlatform: supportedCloudPlatforms.aws,
                    region: DEFAULT_DATASTORE_REGION,
                    resourceType: SupportedResources.k8sPod,
                } as never,
                businessID,
                measurementName: 'my infra measurement',
            },
            subject
        );

        expect(response.measurementConfiguration).toBeUndefined();
        expect(response.message).toEqual('Created Measurement Configuration');
        expect(mockCreateRole).not.toHaveBeenCalled();
        expect(mockPutRolePolicy).not.toHaveBeenCalled();
        expect(mockLoadPoints).toHaveBeenCalledTimes(1);
    });
});

