arguments.newString:
    /**
     * Writes a record which failed processing, together with the metadata of the failure,
     * into the dead letter queue of the SaaS business which produced it.
     *
     * A record which failed processing is never retried by the connector, a failure to write it to the
     * dead letter queue is therefore reported instead of thrown.
     */
    public static async publishToDLQ({
        message,
        s3Key,
        sourceKey,
        businessID,
        error,
    }: {
        message?: string | CreateUsageDto;
        s3Key: string;
        sourceKey: string;
        businessID?: string;
        error?: Error | string;
    }) {
        const Bucket = DatastoreAccessInformation.dlqBucket;
        const Key = DatastoreUsageRecord.dlqKey(sourceKey);
        const Body = JSON.stringify(
            {
                message,
                s3Key,
                sourceKey,
                businessID,
                error: error instanceof Error ? error.message : error,
                processedAt: new Date().toISOString(),
            },
            null,
            2
        );
        try {
            DatastoreUsageRecord.logger.warn(
                `Writing failed usage record to the dead letter queue: s3://${Bucket}/${Key}`
            );
            const s3 = new S3({ region: DEFAULT_DATASTORE_REGION });
            await s3.putObject({ Bucket, Key, Body, ContentType: 'application/json' });
            return { Bucket, Key, published: true };
        } catch (e) {
            DatastoreUsageRecord.logger.error(
                `Failed to write the usage record to the dead letter queue: s3://${Bucket}/${Key}`,
                e
            );
            return { Bucket, Key, published: false };
        }
    }
}

